:root {
  --calendar-dialog-gap: calc(var(--space-base) + var(--space-step));
  --calendar-dialog-row-padding-inline: calc(var(--space-base) + 2 * var(--space-step));
  --calendar-dialog-row-column-gap: var(--calendar-dialog-gap);
  --calendar-dialog-row-content-gap: var(--space-step);
  --calendar-dialog-row-expand-button-padding-inline-start: var(--calendar-dialog-gap);
  --calendar-dialog-expanded-row-content-gap: var(--space-base);
  --calendar-dialog-expanded-row-padding-block: calc(var(--space-base) + 2 * var(--space-step));
  --calendar-border-radius: calc(2 * var(--space-step));
  --calendar-dialog-top-bar-height: var(--space-base);
  --calendar-dialog-title-bar-padding-block: var(--calendar-dialog-gap);
}
